  {
   "@type": "Question",
   "name": "How many times a day do puppies poop?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "Usually about 3 to 5 times a day, more often than adult dogs. They eat more meals and digest quickly, so they often go soon after eating."
   }
  },
  {
   "@type": "Question",
   "name": "How many hours can a puppy hold their pee?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "A common rule is \"their age in months + 1 hour.\" At 3 months that's about 4 hours, but it's closer to a maximum, so take them out more often."
   }
  },
  {
   "@type": "Question",
   "name": "Do small dogs go more often than large dogs?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "Poop count depends more on how much and how often they eat than on size, so most adult dogs go 1 to 2 times a day. Small dogs do tend to pee more often."
   }
  },
  {
   "@type": "Question",
   "name": "My puppy hasn't pooped all day.",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "They may be eating less, or their surroundings may have changed. If they strain and seem uncomfortable, or are vomiting or losing their appetite, talk to your vet."
   }
  }
 ]
